# Crops the app screenshots (docs/sdlc/screens, regenerated by CAPTURE_SCREENS=1 npx playwright test)
# and composes the phone views from ./assets into ./fig for the report.
import os
from PIL import Image
S = '../../sdlc/screens/'
os.makedirs('fig', exist_ok=True)
crops = {
    'shot-landing': ('00-landing', 0, 810), 'shot-signin': ('01-sign-in', 0, 860), 'shot-citizen-overview': ('02-citizen-overview', 0, 900),
    'shot-new-complaint': ('03-citizen-new-complaint', 0, 1000), 'shot-detail': ('04-citizen-complaint-detail', 0, 980),
    'shot-my-complaints': ('05-citizen-my-complaints', 0, 838), 'shot-feedback': ('06-citizen-resolved-feedback', 1120, 780),
    'shot-inbox': ('07-citizen-updates-inbox', 0, 800), 'shot-officer-overview': ('08-officer-overview', 0, 900),
    'shot-queue': ('09-officer-department-queue', 0, 900), 'shot-process': ('10-officer-process-complaint', 0, 1000),
    'shot-admin-overview': ('12-admin-overview-monitoring', 0, 900), 'shot-categories': ('13-admin-service-categories', 0, 720),
    'shot-dispatch': ('14-admin-dispatch-centre', 0, 839), 'shot-analytics': ('15-admin-analytics', 0, 1000),
    'shot-analytics-dark': ('17-admin-analytics-dark', 0, 900), 'shot-map': ('16-officer-department-map', 0, 960),
}
def frame(im):
    b = Image.new('RGB', (im.width + 4, im.height + 4), (150, 158, 154)); b.paste(im, (2, 2)); return b
for name, (f, top, h) in crops.items():
    im = Image.open(S + f + '.png').convert('RGB'); h = min(h, im.height - top)
    frame(im.crop((0, top, im.width, top + h))).save(f'fig/{name}.png')
def phones(files, name, crop_h=1250):
    ims = []
    for f in files:
        im = Image.open(f'assets/{f}--phone.png').convert('RGB'); im = im.resize((360, int(im.height * 360 / im.width)))
        ims.append(frame(im.crop((0, 0, 360, min(crop_h, im.height)))))
    out = Image.new('RGB', (sum(i.width for i in ims) + 40 * (len(ims) - 1), max(i.height for i in ims)), 'white'); x = 0
    for i in ims: out.paste(i, (x, 0)); x += i.width + 40
    out.save(f'fig/{name}.png')
phones(['02-citizen-overview', 'a01-citizen-feedback-form', 'menu-open'], 'shot-phones-citizen')
phones(['14-admin-dispatch-centre', 'a05-admin-users-edit', '15-admin-analytics'], 'shot-phones-admin')
print('screens cropped')
